(function(root){'use strict';const base=root.PaisGuide,records=[{"jobId":"OP-3102","key":"pps_catalog_a6d3cdadacccb9d2","label":"Bronquite plástica — registro no PPS","specific":true,"entity":"Bronquite plástica pediátrica: formação de moldes ramificados nos brônquios, com causas linfáticas, cardíacas ou inflamatórias/infecciosas e risco de obstrução respiratória.","assessment":"{\"classification\":\"VALID_RARE_PEDIATRIC_AIRWAY_CAST_DISEASE_NOT_EQUIVALENT_TO_COMMON_BRONCHITIS\",\"assessment\":\"Nome válido, distinto de bronquite aguda comum, bronquiolite e chiado inespecífico. Molde pode ter material linfático/proteico e células inflamatórias; Fontan é associação importante, não causa obrigatória. Não presumir anatomia, composição, etiologia ou tratamento pelo rótulo.\",\"aliases\":[\"Bronquite plástica\",\"Bronquite plástica — apresentação pediátrica aguda\",\"Bronquite plástica — evolução complicada/refratária\",\"Bronquite plástica — forma grave/crítica\"],\"alias_guard\":\"São qualificadores de apresentação/gravidade, não entidades independentes nem sinônimos de estado estável. Forma grave/crítica atual exige emergência; evolução complicada/refratária exige reavaliação urgente, sem alta domiciliar automática. História de crise já tratada deve seguir plano de alta e não ser confundida com crise atual.\",\"reconciliation\":\"Resultado original OP-3102 presente, status histórico VALIDATED_AI sem publicação; reutilizado como ponto de partida. Não há evidência nesta revisão de novo diagnóstico ou equivalência com bronquite comum. Integração atual e colisões de aliases devem ser verificadas pelo coordenador.\",\"pediatric_scope\":\"Lactentes a adolescentes, preservando raridade em menores e avaliação diferencial. Não extrapolar protocolos Fontan para formas infecciosas nem ensaios hospitalares para casa.\"}","sections":{"CUIDADOS EM CASA":["Bronquite plástica não é a bronquite comum: formam-se moldes dentro dos brônquios que podem bloquear o ar. Os cuidados em casa valem quando a criança está estável e já foi avaliada; crise atual não é situação de alta automática.","Observe mudanças na respiração, cor, disposição, tosse, tolerância ao esforço e saturação, quando houver monitorização e alvo individual prescritos. Um oxímetro aparentemente normal não afasta uma piora visível.","Mantenha acessíveis o plano da pneumologia/cardiologia, contatos, lista de medicamentos e resumo das cirurgias. Compartilhe o plano com escola e cuidadores.","Se sair um molde e a criança respirar confortavelmente, uma foto pode ajudar a equipe. Guarde a amostra apenas conforme orientação do serviço, sem atrasar avaliação. Nunca procure ou puxe material da garganta com dedos ou instrumentos.","Evite fumaça, vape e irritantes. A bronquite plástica em si não passa para outras pessoas, mas uma infecção associada pode transmitir; siga as orientações sobre higiene, vacinas e afastamento."],"MEDIDAS SEM REMÉDIOS":["Na falta de ar, interrompa o esforço, mantenha a criança acompanhada na posição em que respira melhor e procure ajuda. Não a force a deitar nem a faça caminhar para testar melhora.","Se estiver inconsciente ou não respirar normalmente, chame o SAMU 192 e siga as instruções de reanimação do atendente ou seu treinamento. Não atrase o socorro procurando o molde.","Faça fisioterapia respiratória, técnicas de tosse ou uso de colete/dispositivo somente como foram prescritos e ensinados. Não improvise pancadas no tórax, tosse forçada ou exercício; a fisioterapia prescrita não deve ser confundida com essas tentativas caseiras.","Não use vapor quente ou soluções caseiras para tentar dissolver moldes. Na piora importante, nenhuma técnica domiciliar substitui avaliação e desobstrução hospitalar.","Atividade física e retorno à escola dependem do plano individual, especialmente após internação, falta de oxigênio ou desmaio."],"MEDICAMENTOS":["Use somente os medicamentos e dispositivos já prescritos para esta criança. Confira nome, apresentação, via, horários e limite do plano; não repita o resgate indefinidamente se não houver resposta.","Não comece alteplase/tPA, heparina, dornase, solução hipertônica, broncodilatador, corticoide ou antibiótico por conta própria. Há tratamentos especializados para casos selecionados, mas não existe uma receita doméstica universal.","Não suspenda remédios cardíacos ou respiratórios sem orientação. Leve a lista completa, inclusive suplementos, aos atendimentos.","Oxigênio, quando prescrito, deve seguir o alvo e o fluxo do plano individual enquanto se busca ajuda. Não improvise equipamento ou ajuste fora do plano; precisar de mais suporte é sinal de piora.","Eliminar um molde ou melhorar por pouco tempo não garante que toda a via aérea esteja livre. Sintomas persistentes exigem atendimento, não apenas outra dose."],"ALIMENTAÇÃO E LÍQUIDOS":["Quando estiver alerta e respirando confortavelmente, ofereça alimentação habitual em pequenas porções conforme tolerância. Em menores de seis meses, mantenha leite materno ou fórmula conforme o plano habitual, sem oferecer água extra para fluidificar moldes.","Não force comida, líquidos ou mamadas durante grande falta de ar, arroxeamento ou sonolência. Procure atendimento; não tente tratar o molde com bebidas.","Em cardiopatia/Fontan, respeite o plano individual de líquidos, sal e nutrição. Não restrinja nem aumente volumes por conta própria.","Observe redução de mamadas, suor ao mamar, pausas para respirar, menos urina e perda de peso. Avise a equipe; dificuldade importante para mamar ou prostração exige urgência.","Se um procedimento estiver programado, siga apenas o jejum informado pelo serviço. Esta orientação não estabelece jejum prolongado em casa."],"VOLTE IMEDIATAMENTE AO PRONTO ATENDIMENTO":["Chame o SAMU 192 se houver pausa respiratória, inconsciência, respiração ausente/anormal, lábios azulados, desmaio ou dificuldade para acordar.","Procure emergência com grande esforço para respirar, costelas afundando, gemência, exaustão, incapacidade de falar/chorar/mamar ou piora rápida. O molde pode obstruir a via aérea mesmo sem aparecer pela boca.","Saturação abaixo do alvo individual ou em queda, necessidade de mais oxigênio que o plano ou falha do resgate exige atendimento imediato. Não espere uma medida do oxímetro se a criança estiver mal.","Molde eliminado com falta de ar, sangue relevante, dor torácica, palidez intensa ou suor frio precisa de emergência, mesmo após a saída de parte do material.","Em criança com cardiopatia/Fontan, nova cianose, desmaio, palpitações com mal-estar, edema com piora geral ou redução importante da urina exige avaliação urgente.","Em bebê com menos de três meses, temperatura de 38 °C ou mais exige avaliação imediata, mesmo que pareça bem. Em qualquer idade, febre com prostração, desidratação ou dificuldade respiratória é sinal de alerta."],"QUANDO REAVALIAR":["Após novo molde, mudança da respiração ou necessidade de resgate, avise a equipe no mesmo dia; se houver sinais de alarme, vá imediatamente à emergência sem esperar resposta por mensagem.","Mantenha os retornos de pneumologia e, quando aplicável, cardiologia e equipe linfática. O intervalo deve ser definido para a causa e gravidade desta criança; não há um prazo único válido para todos.","Leve o plano, registros de sintomas e saturação quando disponíveis, fotos/amostras obtidas com segurança e documentos de internações ou broncoscopias.","Peça revisão se as crises aumentarem, houver queda de rendimento, despertares por falta de ar, dificuldade alimentar ou perda de peso. Não espere o próximo retorno de rotina se o padrão piorar.","Antes de voltar para casa após uma crise, confirme os limites do resgate, o alvo de oxigênio quando aplicável, contatos e hospital de referência. Ausência de molde visível não exclui obstrução."]},"ageMap":{"u3m":"Nesta idade o diagnóstico é raro e deve ser confirmado pela equipe. Febre de 38 °C ou mais, apneia, cianose, sonolência ou dificuldade para mamar exige avaliação imediata. Não atribuir toda piora à bronquite plástica.","3a5m":"Observe mamadas, cor, pausas respiratórias, retrações e fraldas. Ofereça apenas leite materno ou fórmula habitual quando respirar confortavelmente; não tente puxar material da garganta.","6a11m":"Redução importante da mamada/brincadeira, arroxeamento ou esforço respiratório requer urgência. Chiado isolado não confirma molde; mantenha vigilância para infecção e aspiração.","1a":"Cuidadores devem reconhecer mudança de cor, respiração, disposição e ingestão. A prioridade é socorrer a criança; fotografar ou guardar molde nunca deve atrasar atendimento.","2a5":"A criança pode relatar dor ou eliminar material ramificado ao tossir. Escola precisa conhecer o plano; não forçar tosse ou exercício durante piora importante.","6a11":"Ensine a avisar falta de ar, tontura, dor, queda de rendimento ou saída de molde. Não esconder sintomas para continuar esporte; siga limites individualizados.","12a17":"Treine autonomia com supervisão, uso correto do plano e comunicação precoce. Evite cigarro/vape e prepare a continuidade entre cardiologia, pneumologia e serviços de adultos.","unknown":"A idade não foi informada. Use os alarmes gerais e confirme idade, diagnóstico, cardiopatia/cirurgias, padrão basal e plano da equipe antes de orientar cuidados individualizados."},"refs":[{"id":"pais20261105_op3102_1","name":"A Multicenter, Open-Label Study to Assess the Safety of Nebulized Tissue Plasminogen Activator for the Acute Treatment of Pediatric Plastic Bronchitis: The PLATyPuS Trial","url":"https://pubmed.ncbi.nlm.nih.gov/40910281/"},{"id":"pais20261105_op3102_2","name":"Clinical features and risk factors of plastic bronchitis in Mycoplasma pneumoniae pneumonia children with pulmonary consolidation: a prospective cohort study","url":"https://www.frontiersin.org/journals/pediatrics/articles/10.3389/fped.2026.1830700/full"},{"id":"pais20261105_op3102_3","name":"Plastic Bronchitis","url":"https://www.rchsd.org/health-article/plastic-bronchitis/"},{"id":"pais20261105_op3102_4","name":"Clinical Practice Guidelines: Acute upper airway obstruction","url":"https://www.rch.org.au/clinicalguide/guideline_index/Acute_upper_airway_obstruction/"},{"id":"pais20261105_op3102_5","name":"Clinical Practice Guidelines: Febrile child","url":"https://www.rch.org.au/clinicalguide/guideline_index/Febrile_child/"},{"id":"pais20261105_op3102_6","name":"Plastic Bronchitis","url":"https://www.chop.edu/conditions-diseases/plastic-bronchitis"}],"aliases":["Bronquite plástica","Bronquite plástica — apresentação pediátrica aguda","Bronquite plástica — evolução complicada/refratária","Bronquite plástica — forma grave/crítica"],"alwaysUrgent":false,"resultPath":"references/orientacoes-validadas/parallel-results/REVIEW-20261105-OP-3102.json","resultHash":"5a2cc618beb43344c668021b21cf40aa65317dcab542909ac4fb7bb80c41cc83"},{"jobId":"OP-3104","key":"pps_catalog_082d95f421445d73","label":"Bulimia nervosa — registro no PPS","specific":true,"entity":"Bulimia nervosa pediátrica, principalmente na adolescência: compulsão com perda de controle e compensações recorrentes, sem confirmação diagnóstica por peso, aparência ou episódio isolado.","assessment":"{\"classification\":\"VALID_PEDIATRIC_EATING_DISORDER_WITH_ADOLESCENT_PREDOMINANCE\",\"assessment\":\"Entidade válida; diferenciar de anorexia com compulsão/purgação, compulsão alimentar sem compensação recorrente, transtorno purgativo e vômito orgânico. Peso habitual não exclui risco. Em lactentes e pré-escolares, não extrapolar diagnóstico adolescente: priorizar avaliação pediátrica de alimentação, crescimento, desenvolvimento e causas orgânicas.\",\"reconciliation\":{\"queue_keys_found\":[\"pps_catalog_082d95f421445d73\"],\"queue_status\":\"VALIDATED_AI\",\"queue_guidance\":null,\"publication\":null,\"original_artifact\":\"references/orientacoes-validadas/parallel-results/OP-3104-pps_catalog_082d95f421445d73.json\",\"aliases\":[\"Bulimia nervosa\",\"Bulimia nervosa — apresentação pediátrica aguda\",\"Bulimia nervosa — evolução complicada/refratária\",\"Bulimia nervosa — forma grave/crítica\"],\"alias_rule\":\"Mesma entidade. Os sufixos são descritores administrativos: não comprovam diagnóstico, critério DSM de gravidade ou estabilidade; forma grave/crítica atual exige atendimento imediato, complicada/refratária exige reavaliação prioritária. Não converter nenhum alias em alta automática.\",\"current_generator_verified\":false},\"counting_rule\":\"Um registro e uma entidade clínica; zero entidades adicionais por quatro aliases. Integração e publicação continuam pendentes.\",\"clinical_limit\":\"Não inferir frequência, duração, exames, estabilidade, risco suicida ou tratamento individual.\"}","sections":{"CUIDADOS EM CASA":["Bulimia nervosa é um transtorno alimentar tratável, não falta de força de vontade. Há perda de controle ao comer e tentativas repetidas de compensar. O peso e a aparência não mostram sozinhos a gravidade.","Ouça sem culpar, ameaçar ou comentar corpo e peso. Combine apoio familiar e momentos de conversa privada com o jovem e a equipe. Não transforme refeições ou banheiro em punição.","Siga o plano de supervisão e segurança da equipe. Guarde com segurança medicamentos e produtos que possam ser usados indevidamente; não deixe sozinha a pessoa em perigo imediato.","Registre mudanças relevantes, sem pesagens ou vigilância obsessiva: episódios relatados, produtos usados, desmaio, palpitações, sangue, pouca urina e sofrimento emocional. Leve o plano e as embalagens às consultas.","Compartilhe com escola e familiares apenas o necessário para apoio e segurança. Interrompa bullying e incentivos a dieta restritiva ou exercício punitivo."],"MEDIDAS SEM REMÉDIOS":["Mantenha o padrão de refeições combinado com a equipe; não improvise metas de peso, calorias, jejuns ou exercícios para compensar.","Depois de vomitar, enxágue a boca suavemente com água. Evite escovar imediatamente e combine cuidados regulares com dentista; dor ou sensibilidade precisam de avaliação.","Pare o exercício usado como compensação; não pratique esforço com tontura, palpitação, fraqueza ou dor no peito. A retomada segue avaliação individual.","Não provoque vômito nem utilize produtos para emagrecer ou compensar a alimentação. Procure orientação da equipe para interromper uso indevido de laxantes ou diuréticos com segurança.","Combine atividades tranquilas e um adulto de confiança para momentos de impulso ou sofrimento. Pergunte com calma sobre pensamentos de morte e busque avaliação, sem tratar a fala como chantagem."],"MEDICAMENTOS":["Use apenas o que foi prescrito para esta criança ou adolescente. Esta orientação não inicia remédio, suplemento, reposição de sais ou dose.","Quando indicado pela equipe, medicamento faz parte de um plano que também inclui cuidado psicológico, médico e nutricional; não substitui esse acompanhamento.","Informe todos os produtos usados, inclusive fórmulas para emagrecer, laxantes, diuréticos, estimulantes, suplementos, insulina e energéticos. Não ajuste nem suspenda medicamento prescrito por conta própria; uso indevido exige contato rápido com a equipe.","Vômitos e purgação podem alterar os sais do sangue e o coração. Não tente corrigir isso com potássio, bicarbonato, sal ou misturas caseiras.","Suspeita de dose excessiva, intoxicação ou uso de produto para autoagressão exige emergência. Leve embalagens e não provoque vômito."],"ALIMENTAÇÃO E LÍQUIDOS":["Siga o plano alimentar individual, com regularidade e ambiente sem julgamento. Não faça barganha, punição ou discussão sobre peso durante refeições.","Não compense episódios com jejum, vômito ou exercício. Retome o próximo passo do plano acompanhado pela equipe.","Se estiver alerta, respirando e engolindo bem, mantenha alimentação e líquidos conforme orientação e tolerância. Não force grandes volumes nem bebidas para repor sais.","Não force alimento ou bebida se houver desmaio, confusão, convulsão, dificuldade para respirar ou engolir, dor intensa ou vômito com sangue: procure emergência.","Pouca urina, tontura, fraqueza ou dificuldade de manter líquidos após purgação precisam de avaliação rápida. Diabetes, doença renal ou cardíaca e gravidez possível exigem plano específico; não ajuste insulina, sal ou líquidos por esta ficha."],"VOLTE IMEDIATAMENTE AO PRONTO ATENDIMENTO":["Acione SAMU 192 diante de colapso, desmaio sem recuperação rápida, convulsão, confusão, dificuldade para acordar ou respirar.","Procure emergência por dor no peito, palpitação persistente ou irregular, desmaio ou fraqueza intensa, especialmente depois de vômitos, produtos para compensar ou exercício.","Vômito com sangue, fezes pretas, dor forte ou súbita no peito ou barriga, dificuldade para engolir e distensão importante exigem avaliação imediata.","Não conseguir manter líquidos, urinar muito pouco, ter extremidades frias ou piorar rapidamente pode indicar desidratação grave; não aguarde consulta marcada.","Intenção ou plano de suicídio, tentativa, intoxicação, autoagressão com lesão ou impossibilidade de manter segurança exigem emergência: acompanhe a pessoa, afaste meios perigosos quando seguro e acione SAMU 192 ou pronto atendimento. CVV 188 é apoio, não substitui emergência.","Purgação repetida sem conseguir parar, recusa completa de líquidos ou alimentos, grande quantidade de produto ou manipulação de insulina exigem avaliação urgente, mesmo com peso aparentemente normal. Se o quadro atual foi classificado como grave/crítico, não use esta ficha como autorização de cuidado só em casa."],"QUANDO REAVALIAR":["Procure avaliação médica e de saúde mental especializada o quanto antes diante da suspeita, sem esperar emagrecimento ou todos os sinais. O diagnóstico e a segurança exigem avaliação individual.","Mantenha os retornos combinados, mesmo com melhora. A equipe define a necessidade de exames e acompanhamento cardíaco, nutricional e psicológico; exame normal isolado não exclui o transtorno.","Antecipe o contato se aumentarem os episódios, surgir novo método de compensação, houver isolamento, faltas escolares, piora do humor ou dificuldade de seguir o plano. Evolução complicada ou refratária precisa de reavaliação prioritária.","Qualquer pensamento de morte ou autoagressão merece escuta e avaliação profissional rápida. Se houver intenção, plano, perigo imediato ou dúvida sobre conseguir manter segurança, vá à emergência; não aguarde retorno rotineiro.","Peça um plano escrito com contatos, sinais de alarme, refeições, escola e exercício. A recuperação pode levar tempo e ter recaídas; mantenha apoio sem culpa e reveja a abordagem com a equipe quando necessário."]},"ageMap":{"u3m":"Bulimia nervosa não é diagnóstico esperado no recém-nascido. Vômito, recusa alimentar e pouca urina exigem avaliação pediátrica; febre, prostração, sangue, vômito verde ou dificuldade respiratória são sinais de urgência. Não aplicar plano de adolescente.","3a5m":"Em lactente pequeno, investigue vômito e dificuldade alimentar com pediatria. Vômito com sangue ou verde, prostração importante, dor intensa ou sinais de desidratação exigem pronto atendimento imediatamente; não rotule como bulimia nem force alimento.","6a11m":"Nesta idade, alterações alimentares, regurgitação, engasgos ou crescimento inadequado precisam de avaliação pediátrica e do desenvolvimento, não de um diagnóstico presumido de bulimia.","1a":"Na criança de 1 ano, priorize causas clínicas, alimentares e do desenvolvimento. Vômito, recusa ou perda de crescimento não confirmam bulimia; vômito com sangue ou verde, dor intensa ou sonolência anormal exigem pronto atendimento imediatamente.","2a5":"Em pré-escolares, esta apresentação é incomum e não deve ser inferida por comer muito, esconder alimento ou vomitar. Pediatria deve avaliar alimentação, doença orgânica, desenvolvimento e segurança sem culpa.","6a11":"Em escolares, use linguagem simples para avaliar perda de controle, compensação, bullying e sofrimento. O diagnóstico exige equipe pediátrica; aparência e peso não excluem risco.","12a17":"Adolescentes precisam de escuta privada, apoio familiar apropriado e avaliação dos métodos compensatórios, produtos usados, humor, autoagressão e suicídio. Siga plano especializado sem improvisar dieta ou medicamento.","unknown":"Confirme idade e desenvolvimento. O conteúdo é principalmente pertinente a escolares maiores e adolescentes; em crianças pequenas, priorize avaliação pediátrica de causas orgânicas e do desenvolvimento. Instabilidade, sangramento ou perigo de autoagressão exigem emergência."},"refs":[{"id":"pais20261105_op3104_1","name":"Managing Emergencies in Eating Disorders — Physical and Psychiatric Risk Assessment Tool","url":"https://www.rcpsych.ac.uk/docs/default-source/members/faculties/eating-disorders/eating-disorders---meed-physical-and-psychiatric-risk-assessment-tool.pdf?sfvrsn=ca1c28d1_6"},{"id":"pais20261105_op3104_2","name":"Practice Parameter for the Assessment and Treatment of Children and Adolescents With Eating Disorders","url":"https://www.aacap.org/App_Themes/AACAP/docs/practice_parameters/Eating%20Disorders%20JAACAP%20Submit%20final.pdf"},{"id":"pais20261105_op3104_3","name":"Randomized Clinical Trial of Family-Based Treatment and Cognitive-Behavioral Therapy for Adolescent Bulimia Nervosa","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4624104/"},{"id":"pais20261105_op3104_4","name":"Suicídio (Prevenção)","url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/s/suicidio-prevencao/suicidio-prevencao"},{"id":"pais20261105_op3104_5","name":"Bulimia","url":"https://www.nhs.uk/mental-health/conditions/bulimia/"},{"id":"pais20261105_op3104_6","name":"Eating Disorders: What You Need to Know","url":"https://www.nimh.nih.gov/health/publications/eating-disorders"},{"id":"pais20261105_op3104_7","name":"Clinical Practice Guidelines: Vomiting","url":"https://www.rch.org.au/clinicalguide/guideline_index/Vomiting/"},{"id":"pais20261105_op3104_8","name":"Dental Erosion","url":"https://www.ada.org/resources/ada-library/oral-health-topics/dental-erosion"}],"aliases":["Bulimia nervosa","Bulimia nervosa — apresentação pediátrica aguda","Bulimia nervosa — evolução complicada/refratária","Bulimia nervosa — forma grave/crítica"],"alwaysUrgent":false,"resultPath":"references/orientacoes-validadas/parallel-results/REVIEW-20261105-OP-3104.json","resultHash":"391ed912407fb227b0c780f77a3b663f9593e8ffa66e3b3291b6f701733897b8"},{"jobId":"OP-3105","key":"pps_catalog_4dd56b8652d5147b","label":"Bursite aguda — registro no PPS","specific":true,"entity":"Bursite aguda pediátrica: inflamação dolorosa e localizada de uma bursa, estrutura com líquido que reduz o atrito entre pele, tendões, ligamentos e osso, geralmente relacionada a pressão repetida, sobrecarga ou impacto, mas que exige excluir infecção, lesão estrutural e doença articular quando há calor, vermelhidão, febre, incapacidade funcional ou piora","assessment":"{\"classification\":\"VALID_ACUTE_PERIARTICULAR_INFLAMMATORY_ENTITY_REQUIRES_SITE_CONFIRMATION_AND_SEPTIC_EXCLUSION\",\"normalized_entity\":\"Bursite aguda pediátrica\",\"assessment\":\"O termo é válido, mas incompleto para decisão individual: não informa bursa, lateralidade, mecanismo, ferida, febre, imunidade, alcance do movimento nem se o inchaço é realmente extra-articular. 'Registro no PPS' é sufixo administrativo sem significado clínico.\",\"anatomic_and_differential_boundary\":{\"bursitis\":\"Dor e inchaço ficam sobre uma bursa, muitas vezes superficial em joelho ou cotovelo, e podem piorar com pressão ou movimento próximo.\",\"trauma\":\"Impacto, queda, uso repetitivo ou sobrecarga podem irritar a bursa, mas fratura, lesão tendínea, hemartrose e lesão não acidental precisam ser consideradas conforme história e exame.\",\"septic_bursitis\":\"Infecção da bursa pode causar calor, vermelhidão, dor, flutuação, drenagem e febre; é incomum em crianças, porém pode complicar com osteomielite ou artrite séptica.\",\"septic_arthritis\":\"Infecção dentro da articulação costuma causar dor importante e grande limitação do movimento; é emergência ortopédica e não deve ser rotulada como bursite por aparência externa.\",\"cellulitis\":\"Infecção da pele/subcutâneo pode produzir vermelhidão e calor difusos, eventualmente sem coleção bursal definida; pode coexistir e precisa de avaliação.\",\"growing_pains\":\"Dor de crescimento é diagnóstico de exclusão, costuma ocorrer em criança bem, frequentemente bilateral e à noite; inchaço, vermelhidão, calor, febre ou claudicação não são padrão e não devem ser explicados como crescimento.\"},\"not_automatically_equivalent_to\":[\"artrite séptica ou inflamatória, sinovite transitória ou derrame articular\",\"celulite, abscesso, osteomielite ou bursite séptica\",\"fratura, luxação, lesão tendínea, hemartrose ou contusão simples\",\"dor de crescimento, dor muscular ou dor referida de outra articulação\",\"indicação automática de anti-inflamatório, analgésico, antibiótico, corticoide, aspiração, infiltração, imagem ou fisioterapia\"],\"critical_context_to_confirm\":[\"qual bursa/região está envolvida, lado, início, mecanismo, esporte, pressão repetida, queda, ferida, picada ou procedimento\",\"febre, calafrios, prostração, piora rápida, vermelhidão em expansão, listras vermelhas, pus ou drenagem\",\"capacidade de movimentar a articulação, apoiar peso, caminhar ou usar o membro e se a dor é superficial ou profunda\",\"imunossupressão, diabetes, doença falciforme, hemofilia, doença reumatológica, infecção recente e medicamentos em uso\",\"dor noturna constante, perda de peso, palidez, manchas roxas inexplicadas, múltiplas articulações ou episódios recorrentes\",\"plano já prescrito, resposta a repouso/proteção local e prazo de retorno combinado\"],\"urgency_rule\":\"Febre ou aspecto doente com região muito vermelha, quente, dolorosa ou drenando; incapacidade aguda de apoiar peso ou usar o membro; dor intensa com movimento muito limitado; piora rápida; trauma com deformidade ou alteração neurovascular; ou sinais de sepse exigem avaliação urgente/emergencial. Ausência de febre não exclui infecção, especialmente em lactentes ou imunocomprometidos.\",\"age_scope_rule\":\"Bursite pode ocorrer em qualquer idade, mas é menos comum em lactentes e crianças pequenas, que não localizam bem a dor. Nesses grupos, inchaço, choro ao mover, pseudoparalisia ou recusa de apoiar peso exigem avaliação mais precoce e não devem receber diagnóstico domiciliar de bursite.\",\"counting_rule\":\"Contar esta chave como uma entidade clínica específica de bursite aguda. Não contar trauma, celulite, artrite, osteomielite ou dor de crescimento como entidades resolvidas apenas porque aparecem no diagnóstico diferencial. Qualificadores de gravidade são aliases, não novas doenças.\",\"resolution\":\"Termo preservado e normalizado com limitação anatômica e infecciosa. Nenhum paciente, local, etiologia, medicamento, dose, exame, aspiração, infiltração ou antibiótico foi inferido do rótulo.\"}","sections":{"CUIDADOS EM CASA":["Bursite é a inflamação de uma pequena bolsa que reduz o atrito perto de uma articulação. Pressão repetida, movimento repetitivo ou impacto podem irritá-la; infecção também é possível.","Estas medidas servem apenas após avaliação profissional, confirmação do diagnóstico e autorização de cuidado em casa. Um membro inchado não deve ser diagnosticado como bursite pela família.","Evite apoiar ou pressionar a região dolorida e suspenda a atividade que provoca dor. Não force treino, corrida ou movimentos dolorosos.","Se orientada, use compressa fria envolta em pano por períodos curtos, sem gelo direto ou faixa apertada. Retire se houver dor maior, palidez ou dormência.","Acompanhe dor, inchaço, cor e uso do membro. Não fure, esprema ou tente drenar. Vermelhidão nova ou crescente, listras vermelhas, pus ou piora exigem avaliação."],"MEDIDAS SEM REMÉDIOS":["Repouso relativo não significa ficar imóvel indefinidamente: siga a orientação recebida e mantenha apenas atividades que não provoquem dor. Não force uma articulação muito dolorosa.","Use proteção, faixa ou imobilizador somente conforme o plano profissional. Retire pressão excessiva e procure ajuda se mão ou pé ficar frio, pálido, arroxeado ou dormente.","Retome movimento e atividade de forma gradual, conforme orientação e melhora. Se dor ou inchaço reaparecerem, reduza a atividade e reavalie.","Informe a escola e evite esporte com dor ou perda de função. Revise pressão repetida, carga de treino e equipamento antes do retorno.","Não faça massagem forte, agulhamento, infiltração caseira ou calor intenso. O cuidado local nunca deve atrasar atendimento quando houver sinal de infecção ou lesão importante."],"MEDICAMENTOS":["Use somente medicamento prescrito ou autorizado para esta criança, na apresentação, intervalo e duração indicados. Não use sobra de receita nem combine produtos com o mesmo princípio ativo.","Esta orientação não escolhe analgésico, anti-inflamatório, antibiótico, corticoide ou dose. Idade, peso, alergias, hidratação, doenças associadas e outros remédios precisam ser considerados.","Antibiótico não é tratamento automático de bursite por sobrecarga. Suspeita de infecção requer avaliação; não tente coletar líquido, drenar ou aplicar medicamento na região em casa.","Se a dor exigir mais remédio do que o plano prevê, procure reavaliação em vez de aumentar a dose por conta própria. Falta de ar, inchaço de língua ou desmaio após medicamento exigem emergência."],"ALIMENTAÇÃO E LÍQUIDOS":["Mantenha a alimentação e os líquidos habituais adequados à idade; a bursite não exige dieta especial ou suplemento.","Em lactentes, mantenha o leite habitual. Não substitua mamadas por chás, suplementos ou líquidos para tratar o inchaço.","Observe redução importante de mamadas, recusa de líquidos ou pouca urina, principalmente se houver febre ou prostração. Esses sinais exigem avaliação.","Respeite eventual restrição de líquidos ou jejum já informado pela equipe. Não ofereça nada pela boca se a criança estiver inconsciente ou com dificuldade para engolir."],"VOLTE IMEDIATAMENTE AO PRONTO ATENDIMENTO":["Febre ou mal-estar com região inchada, quente, vermelha ou dolorosa; vermelhidão que se espalha, listras vermelhas, pus ou dor em rápida piora: procure atendimento imediato para avaliar infecção.","Incapacidade súbita de andar, apoiar peso, movimentar a articulação ou usar o membro exige pronto atendimento. Pode haver problema no osso ou na articulação, não apenas na bursa.","Após trauma, deformidade, perda de sensibilidade, mão ou pé frio/arroxeado ou dor muito intensa exigem emergência. Proteja o membro sem tentar colocá-lo no lugar.","Acione o SAMU 192 se houver pouca resposta, dificuldade para acordar, respiração anormal, pele muito fria/manchada ou deterioração rápida.","Em menores de 3 meses, temperatura de 38°C ou mais exige avaliação imediata. Em qualquer bebê, recusa de mover um membro, choro ao movimentar, inchaço ou mamadas muito reduzidas também precisam de avaliação rápida, mesmo sem febre."],"QUANDO REAVALIAR":["Siga o retorno combinado. Se a região não estiver melhorando com o cuidado indicado, contate a equipe para antecipar a revisão; não espere pelo retorno se surgir algum alarme.","Se a criança continua mancando, deve haver revisão em até 7 dias do início da claudicação, ou antes conforme a avaliação inicial. Piora ou incapacidade de apoiar peso exige atendimento imediato, sem esperar esse prazo.","Dor noturna persistente, perda de peso, palidez, manchas roxas sem explicação, rigidez matinal, vários locais afetados ou recorrência precisam de nova avaliação. Não espere quatro semanas para buscar ajuda.","Inchaço, calor, vermelhidão, febre ou mancar não devem ser explicados como dor de crescimento. Um exame normal isolado não exclui infecção inicial se a criança piorar.","Antes do retorno completo ao esporte, confirme recuperação do movimento e ausência de dor ou inchaço relevantes. Casos com infecção, trauma importante ou recorrência exigem liberação individual."]},"ageMap":{"u3m":"Bursite por sobrecarga é incomum em bebê pequeno. Temperatura de 38°C ou mais, inchaço, recusa de mover um membro, choro ao movimentar ou mamadas muito reduzidas exigem avaliação imediata; não presumir bursite simples.","3a5m":"Observe assimetria de movimento, choro ao vestir ou trocar fralda, calor e inchaço. O bebê não localiza a dor e precisa de exame rápido nesses casos, mesmo sem febre. Mantenha o leite habitual.","6a11m":"Recusa nova de engatinhar, apoiar-se ou usar braço/perna, especialmente com calor, inchaço ou febre, exige avaliação imediata. A ausência de queda presenciada não exclui lesão ou infecção.","1a":"A criança pode apontar para outro lugar. Recusa de andar ou apoiar peso, grande limitação de movimento e dor intensa exigem pronto atendimento, não apenas cuidado de uma suposta bursite.","2a5":"Observe brincadeiras, quedas, feridas e uso do membro. Inchaço focal ou mancar não é padrão de dor de crescimento; reavalie precocemente e siga os sinais de urgência.","6a11":"Ajoelhar, apoiar o cotovelo, arremessar e impacto esportivo podem irritar bursas. Só retome carga gradualmente após avaliação; não treine com dor, inchaço ou perda de função.","12a17":"Revise esporte, trabalho, técnica, equipamentos e pressão repetida. Inclua o adolescente no plano e evite automedicação. Recorrência ou rigidez matinal precisa de investigação.","unknown":"Confirme idade, local, mecanismo, febre e capacidade de usar o membro com a equipe. Sem avaliação diagnóstica, esta ficha não autoriza cuidado domiciliar de um membro doloroso ou inchado; aplique os alertas de urgência."},"refs":[{"id":"pais20261105_op3105_1","name":"Bursitis: Causes, Symptoms and Treatment","url":"https://www.nationwidechildrens.org/conditions/bursitis"},{"id":"pais20261105_op3105_2","name":"Clinical Practice Guidelines: The acutely swollen joint","url":"https://www.rch.org.au/clinicalguide/guideline_index/The_acutely_swollen_joint/"},{"id":"pais20261105_op3105_3","name":"Clinical Practice Guidelines: The limping or non-weight bearing child","url":"https://www.rch.org.au/clinicalguide/guideline_index/The_limping_or_non-weight_bearing_child/"},{"id":"pais20261105_op3105_4","name":"Septic bursitis in childhood","url":"https://pubmed.ncbi.nlm.nih.gov/7042753/"},{"id":"pais20261105_op3105_5","name":"Growing Pains Are Normal Most Of The Time","url":"https://www.healthychildren.org/English/health-issues/conditions/orthopedic/Pages/growing-pains-are-normal-most-of-the-time.aspx"},{"id":"pais20261105_op3105_6","name":"Clinical Practice Guidelines: Febrile child","url":"https://www.rch.org.au/clinicalguide/guideline_index/Febrile_child/"}],"aliases":["Bursite aguda","Bursite aguda — apresentação pediátrica aguda","Bursite aguda — evolução complicada/refratária","Bursite aguda — forma grave/crítica"],"alwaysUrgent":false,"resultPath":"references/orientacoes-validadas/parallel-results/REVIEW-20261105-OP-3105.json","resultHash":"e490fc7c1c1ed081f6b709afa0c370b517d7412315f15ee4718f7851f4818d65"},{"jobId":"OP-3112","key":"pps_catalog_b7be3459d9156c27","label":"Cardiomiopatia hipertrófica — registro no PPS","specific":true,"entity":"Cardiomiopatia hipertrófica pediátrica: fenótipo de espessamento miocárdico desproporcional ao tamanho corporal e não explicado somente por carga anormal, cuja causa, obstrução, arritmias e risco devem ser definidos individualmente.","assessment":"{\"classification\":\"VALID_PEDIATRIC_PHENOTYPE_WITH_UNSPECIFIED_ETIOLOGY_AND_RISK\",\"assessment\":\"Termo válido. O sufixo registro no PPS é administrativo e não cria entidade. Distinguir fenótipo confirmado, portador genético sem hipertrofia, hipertrofia secundária e condições sindrômicas/metabólicas associadas. Não presumir forma sarcomérica, obstrutiva, arritmia ou alto/baixo risco pelo rótulo.\",\"counting_rule\":\"Um registro candidato a orientação específica. Zero nova entidade contabilizada nesta revisão: reconciliar equivalência com fichas canônicas antes de contar publicação. Aliases de gravidade ou refratariedade não são novas doenças e não autorizam orientação domiciliar indiferenciada.\",\"genotype_boundary\":\"Variante genética sem hipertrofia não equivale a cardiomiopatia fenotípica; teste genético negativo não exclui toda hereditariedade.\",\"risk_boundary\":\"Risco pediátrico é multifatorial e longitudinal. Modelos têm populações próprias; não usar número doméstico nem extrapolar modelos de adultos, de HCM isolada ou de fenótipo positivo para toda criança.\",\"population\":\"Lactentes, crianças e adolescentes com diagnóstico confirmado ou suspeita em avaliação; não define etiologia nem tratamento individual.\"}","sections":{"CUIDADOS EM CASA":["Cardiomiopatia hipertrófica significa que parte do músculo do coração está mais espessa do que o esperado. Pode dificultar o enchimento ou a saída do sangue e favorecer alterações do ritmo. A evolução varia: estar sem sintomas não significa risco zero.","Mantenha o acompanhamento com cardiologia pediátrica. Leve receitas e exames anteriores e anote quando ocorreram palpitações, dor no peito, tontura, desmaio ou mudança na disposição, especialmente durante esforço.","Em bebês, observe mamadas mais fracas ou demoradas, respiração rápida, sonolência incomum e dificuldade para ganhar peso. Em maiores, pergunte sobre cansaço, falta de ar e sintomas na escola e nas brincadeiras.","Relógios, aplicativos e oxímetros não substituem avaliação do ritmo nem classificam o risco. Não atrase atendimento para repetir medições.","A equipe orientará se parentes precisam de avaliação e aconselhamento genético. Ter uma variante genética não significa necessariamente que já exista espessamento do coração; não atribua culpa à família."],"MEDIDAS SEM REMÉDIOS":["Evite a proibição indiscriminada de brincar, mas não libere treino intenso ou competição por conta própria. Combine atividades e limites com a equipe, conforme sintomas e avaliação atual.","Interrompa o esforço diante de dor no peito, tontura, palpitação ou falta de ar diferente do habitual. Não retome a atividade após desmaio sem avaliação.","Escola e cuidadores devem conhecer o plano de emergência. Em atividades organizadas, combine acesso a desfibrilador externo automático (DEA) e pessoas treinadas para reanimação, sem pressionar a criança a ultrapassar seus limites.","Evite fumaça, vape, energéticos, pré-treinos e outras substâncias estimulantes. Discuta suplementos e remédios de venda livre com a equipe.","Se a criança não responder e não respirar normalmente, acione SAMU 192, peça um DEA e inicie reanimação conforme treinamento ou instruções do atendente. Não espere documentos ou medições domésticas."],"MEDICAMENTOS":["Dê somente os medicamentos e apresentações já prescritos. Não suspenda, dobre ou troque a dose por conta própria, inclusive quando a criança estiver bem.","A escolha do tratamento depende da causa, sintomas, função, obstrução e ritmo cardíacos. Esta orientação não indica medicamento, dose, cirurgia ou dispositivo automaticamente.","Avise a equipe sobre possíveis efeitos adversos e antes de usar descongestionantes, estimulantes, fitoterápicos ou suplementos. Não use receita de outra pessoa.","Se vômitos ou recusa impedirem manter o tratamento, contate o serviço no mesmo dia; não repita automaticamente uma dose vomitada. Desmaio ou sinais de alarme exigem emergência, não apenas contato programado."],"ALIMENTAÇÃO E LÍQUIDOS":["Mantenha alimentação adequada à idade e o plano individual da cardiologia. Não restrinja nem aumente água, sal, calorias ou fórmula apenas pelo nome do diagnóstico.","Em bebês, acompanhe a disposição para mamar e o crescimento. Procure avaliação se a alimentação piorar, especialmente junto de respiração rápida ou sonolência.","Com falta de ar importante, sonolência anormal ou desmaio, não force líquidos ou alimentos pela boca: procure atendimento.","Em calor, febre, vômitos ou diarreia, peça orientação precoce se beber ou urinar menos. Quantidade de líquidos deve respeitar o plano individual; não compense com grande volume de uma vez."],"VOLTE IMEDIATAMENTE AO PRONTO ATENDIMENTO":["Acione SAMU 192 diante de colapso, ausência de resposta, respiração ausente ou anormal, cor azulada/cinza ou dificuldade importante para acordar.","Qualquer desmaio novo sem explicação em criança com cardiomiopatia precisa de avaliação imediata, sobretudo durante esforço ou acompanhado de dor ou palpitação, mesmo que recupere rapidamente.","Procure emergência por dor no peito importante ou persistente, palpitação com tontura intensa, falta de ar ou desmaio, ou fraqueza marcante com palidez e suor frio.","Falta de ar intensa, pele fria/manchada, confusão ou redução importante da urina com piora do estado geral podem indicar circulação inadequada.","Em lactente, dificuldade intensa para mamar junto de esforço respiratório, cor alterada ou sonolência exige atendimento imediato. Não aguarde a próxima consulta."],"QUANDO REAVALIAR":["Compareça na data definida pela cardiologia, mesmo sem sintomas. Se não houver retorno marcado, contate o serviço para organizar o seguimento; o intervalo varia com idade, causa e evolução.","O plano de atividade deve ser revisto pelo menos anualmente e antes se houver sintomas ou mudança do quadro. Isso não substitui consultas mais próximas já indicadas.","Procure orientação no mesmo dia para nova redução de disposição, alimentação ou tolerância às atividades, palpitação recorrente sem sinais intensos, ou dificuldade de manter o tratamento. Se houver sinal de alarme, vá imediatamente à emergência.","Após atendimento por desmaio ou outro episódio cardíaco, siga o retorno e a liberação de atividade dados pelo serviço; não considere a melhora isolada uma autorização para voltar ao esporte.","Informe novos diagnósticos cardíacos ou morte súbita na família na reavaliação. A equipe decidirá o rastreamento dos parentes e os exames necessários."]},"ageMap":{"u3m":"No lactente pequeno, priorize mamadas, respiração, alerta e crescimento. Dificuldade para mamar com esforço respiratório, cor alterada ou sonolência é emergência; início precoce não identifica sozinho a causa.","3a5m":"Observe se mamar ficou mais difícil ou demorado e se há respiração rápida ou mais sono. Piora importante ou associação com cor anormal exige atendimento imediato.","6a11m":"Compare alimentação, interação, movimento e respiração com o habitual. Não force comida ou líquidos se houver falta de ar importante ou sonolência.","1a":"Menos brincadeira, pausas incomuns, recusa alimentar ou moleza podem ser a forma de mostrar sintomas. Desmaio, cor azulada/cinza ou piora rápida exigem emergência.","2a5":"Observe pausas para respirar, dificuldade de acompanhar brincadeiras e queixas de dor. Cuidadores precisam conhecer o plano de atividade e os sinais de alarme.","6a11":"Pergunte sobre dor, palpitação, tontura ou desmaio em educação física e recreio. A escola deve seguir o plano individual e não pressionar desempenho.","12a17":"Inclua o adolescente nas decisões sobre treino, competição e adesão; revise energéticos, pré-treinos, vape e outras substâncias sem julgamento. Desmaio ou palpitação com mal-estar exige avaliação imediata.","unknown":"Confirme a idade para adaptar rotina e seguimento. Isso nunca deve atrasar atendimento diante de desmaio, colapso, dificuldade respiratória ou outros sinais de alarme."},"refs":[{"id":"pais20261105_op3112_1","name":"AHA Clinical Update: 2024 Guideline for the Management of Hypertrophic Cardiomyopathy","url":"https://professional.heart.org/-/media/PHD-Files/Education/2024_HCM_Guideline_for_the_Management_of_HCM_Slide_Deck.pdf"},{"id":"pais20261105_op3112_2","name":"Physical Activity in Pediatric Cardiomyopathies: Top Things to Know","url":"https://professional.heart.org/en/science-news/physical-activity-in-pediatric-cardiomyopathies/top-things-to-know"},{"id":"pais20261105_op3112_3","name":"Hypertrophic cardiomyopathy in children","url":"https://www.childrens.com/specialties-services/conditions/hypertrophic-cardiomyopathy"},{"id":"pais20261105_op3112_4","name":"Pediatric heart failure","url":"https://www.childrens.com/specialties-services/conditions/heart-failure"},{"id":"pais20261105_op3112_5","name":"Cardiomyopathy — Living With","url":"https://www.nhlbi.nih.gov/health/cardiomyopathy/living-with"},{"id":"pais20261105_op3112_6","name":"Cardiac Arrest — What Is Cardiac Arrest?","url":"https://www.nhlbi.nih.gov/health/cardiac-arrest"},{"id":"pais20261105_op3112_7","name":"A Validated Model for Sudden Cardiac Death Risk Prediction in Pediatric Hypertrophic Cardiomyopathy","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7365676/"},{"id":"pais20261105_op3112_8","name":"Inherited Cardiovascular Diseases","url":"https://www.gosh.nhs.uk/wards-and-departments/departments/clinical-specialties/inherited-cardiovascular-diseases/"}],"aliases":["Cardiomiopatia hipertrófica"],"alwaysUrgent":false,"resultPath":"references/orientacoes-validadas/parallel-results/REVIEW-20261105-OP-3112.json","resultHash":"f9e186719a67635a065de4521d8c77bd24e2c2e47ab0fbda1ba797e1b3f16724"},{"jobId":"OP-3114","key":"pps_catalog_928bd8c641ed4bd9","label":"Cardiopatia congênita cianótica — registro no PPS","specific":true,"entity":"Cardiopatia congênita cianótica pediátrica — grupo/fenótipo, anatomia não especificada","assessment":"{\"classification\":\"VALID_PEDIATRIC_CLINICAL_GROUP_NOT_ONE_ANATOMIC_DISEASE\",\"assessment\":\"Termo válido como grupo/fenótipo: não identifica defeito anatômico, circulação atual, etapa cirúrgica ou saturação individual. Oferece orientação específica transversal para crianças com cardiopatia cianótica, sem cobrir automaticamente cada lesão estrutural.\",\"anatomy_boundary\":\"Tetralogia de Fallot, transposição das grandes artérias, atresias, retorno venoso pulmonar anômalo, truncus e fisiologia univentricular não são equivalentes entre si nem podem ser inferidos do rótulo.\",\"hypercyanotic_spell_boundary\":\"Crise hipercianótica é episódio agudo, sobretudo em Fallot/atresia pulmonar e determinadas fisiologias com fluxo pulmonar reduzido. Não é toda mudança de cor. Reconhecimento, acalmar e posição joelhos-peito fazem parte de planos de crise conhecidos; a ficha não proíbe medidas previamente ensinadas, nem as generaliza a qualquer cardiopatia ou substitui atendimento emergencial.\",\"duct_dependence_boundary\":\"Ducto-dependência é fisiologia neonatal distinta. Cianose nova, choque, má perfusão ou deterioração alimentar/respiratória do recém-nascido exigem emergência. Não iniciar prostaglandina ou oxigênio sem equipe.\",\"baseline_boundary\":\"A cianose/saturação basal já documentada pode diferir do normal populacional. Piora nova, mudança relevante ou valor além do limite do plano exige ação; estabilidade não pode ser decidida só pela cor ou um número. Na circulação univentricular entre cirurgias, qualquer alerta do plano exige contato precoce, sem transpor metas para outras anatomias.\",\"heart_failure_boundary\":\"Cianose não é sinônimo de insuficiência cardíaca. Dispneia, fadiga alimentar, suor, perfusão ruim, edema e crescimento insuficiente exigem avaliação própria.\",\"counting_rule\":\"Um registro e um grupo clínico orientado, não uma nova doença anatômica nem cobertura integral de todas as cardiopatias congênitas. Sufixo administrativo e aliases de gravidade não criam entidades adicionais. Não somar crise hipercianótica, ducto-dependência ou insuficiência cardíaca como condições resolvidas.\",\"resolution\":\"Orientação específica de grupo; preservar nomes/IDs e remeter o plano terapêutico e a evolução à anatomia e estágio reais.\"}","sections":{"CUIDADOS EM CASA":["Cardiopatia congênita cianótica reúne diferentes defeitos do coração presentes desde o nascimento. A circulação pode levar menos oxigênio ao corpo. O nome não informa qual é o defeito nem qual cor ou saturação é esperada: siga o diagnóstico e o plano da cardiologia pediátrica.","Conheça o padrão de cor, respiração, energia, alimentação e urina da criança. Uma coloração já conhecida e estável não deve ser confundida com piora súbita; cor azulada ou acinzentada nova, respiração difícil ou moleza exigem avaliação imediata.","Guarde resumo do defeito, cirurgias e cateterismos, lista de medicamentos, contatos e plano de urgência. Cirurgia ou melhora da cor não significa necessariamente cura: mantenha seguimento.","Se houver programa de monitorização em casa, anote peso, alimentação e saturação exatamente como ensinado. Avise a equipe quando os limites do plano forem ultrapassados; não espere sintomas intensos nem use uma leitura isolada para se tranquilizar.","Combine com escola e cuidadores quais atividades são permitidas, o que é habitual e quando pedir ajuda. Não exclua a criança automaticamente da escola ou das brincadeiras."],"MEDIDAS SEM REMÉDIOS":["Atividades e esporte devem respeitar o plano individual. Pare a atividade se aparecer falta de ar fora do habitual, cor pior, dor no peito, palpitação, tontura ou desmaio; procure ajuda conforme os sinais de alarme.","Se uma crise de cianose ocorrer, mantenha a criança calma e junto do cuidador, evitando agitação e manuseio desnecessário. Se a cardiologia já ensinou posição com joelhos junto ao peito para crises da cardiopatia específica, siga esse plano enquanto busca ajuda. Não force posições nem suponha que toda mudança de cor seja esse tipo de crise.","Crise que não melhora rapidamente, dificuldade respiratória, moleza ou perda de resposta exige SAMU 192. Não atrase o chamado para repetir medidas. Se não responder e não respirar normalmente, siga as instruções do atendente para reanimação e uso de DEA, se disponível.","Evite fumaça de cigarro/vape e contato próximo com pessoas doentes. Mantenha vacinação, saúde bucal e cuidados habituais conforme orientação pediátrica/cardiológica.","Oxímetro não substitui avaliação. Utilize o sensor e a técnica ensinados; leitura inesperada deve ser conferida sem atrasar socorro quando a criança estiver pior. Não procure atingir uma saturação universal por conta própria."],"MEDICAMENTOS":["Use somente os medicamentos prescritos para a criança. Esta orientação não define remédio, dose, intervalo ou duração: o tratamento varia conforme o defeito e a circulação atual.","Confira nome, apresentação e horário. Não suspenda, dobre, substitua ou repita uma dose vomitada sem orientação da equipe ou do plano escrito.","Não inicie nem ajuste oxigênio por conta própria. Se já há prescrição e plano de urgência, siga-os; oxigênio não corrige todas as causas de cianose e não substitui atendimento.","Antes de usar remédio sem receita, suplemento, fitoterápico ou energético, consulte a equipe sobre segurança e interações. Leve a lista completa de medicamentos e alergias aos atendimentos.","Procedimentos odontológicos podem exigir orientações específicas em alguns defeitos; não tome antibiótico preventivo automaticamente. A necessidade deve ser definida para o diagnóstico e o procedimento reais."],"ALIMENTAÇÃO E LÍQUIDOS":["Bebês com cardiopatia podem cansar ao mamar e ganhar peso mais lentamente. Acompanhe a curva de crescimento com a equipe; isso não significa falha da família.","Mantenha leite materno quando possível e conforme o plano. Porções menores e mais frequentes, com pausas, podem ajudar lactentes estáveis quando orientadas pela equipe. Mamada progressivamente fraca ou interrompida por falta de ar precisa de avaliação.","Não altere a concentração da fórmula nem acrescente pó, sal, açúcar, espessante ou suplemento sem receita específica. Fortificação, sonda e metas calóricas pertencem ao plano nutricional individual.","Não force nem restrinja líquidos sem orientação escrita. Necessidades mudam com idade, cirurgia, função cardíaca/renal e medicamentos. Redução de ingestão, vômitos, diarreia ou menos urina devem ser comunicados prontamente à equipe.","Não ofereça comida ou bebida durante falta de ar intensa, sonolência importante, desmaio, convulsão ou engasgos repetidos. Procure emergência."],"VOLTE IMEDIATAMENTE AO PRONTO ATENDIMENTO":["Acione SAMU 192 se a criança ficar sem resposta, não respirar normalmente, tiver convulsão, desmaio sem recuperação rápida ou dificuldade importante para acordar.","Procure emergência por cor azulada/acinzentada nova ou claramente pior, sobretudo com respiração rápida, profunda ou difícil, retrações, gemência, agitação intensa ou moleza. Não espere o oxímetro confirmar.","Pele fria/manchada com prostração, pulso muito fraco, quase nenhuma urina ou piora rápida pode indicar circulação insuficiente e exige emergência, mesmo sem grande mudança na saturação.","Em recém-nascido ou lactente, piora da alimentação acompanhada de alteração da cor, respiração, alerta ou perfusão exige atendimento imediato. Bebê com menos de 3 meses e temperatura de 38°C ou mais também precisa de avaliação imediata.","Dor torácica importante, desmaio durante esforço, palpitação com mal-estar, tosse com sangue ou febre com prostração/piora respiratória exige avaliação urgente.","Fraqueza de um lado, rosto torto, fala ou visão subitamente alterada ou nova convulsão exige SAMU 192. Não dê nada pela boca se houver alteração da consciência ou dificuldade para engolir."],"QUANDO REAVALIAR":["Cumpra os retornos da cardiologia, inclusive quando a criança está bem ou já foi operada. O intervalo depende da anatomia, etapa do tratamento, crescimento e funcionamento do coração; esta ficha não substitui esse calendário.","Contate a equipe no mesmo dia diante de mudança leve, mas persistente, de cansaço, alimentação, suor, urina, inchaço ou rendimento, se a criança estiver estável e sem os sinais de emergência acima. Não aguarde retorno marcado se estiver piorando.","No período entre cirurgias de uma circulação univentricular, siga o contato imediato estabelecido pelo programa ao ocorrer qualquer alerta de peso, alimentação, saturação ou sintomas. Não adote os limites de outra criança.","Após episódio novo de cianose, desmaio ou palpitação, obtenha orientação da equipe; mesmo quando melhora, o episódio pode exigir revisão. Se não houver recuperação rápida/completa ou houver sinais graves, vá à emergência.","Antecipe orientação se a curva de crescimento piorar, mamadas ficarem cansativas ou a criança parar de acompanhar atividades habituais. Atualize o plano após internação, cirurgia, cateterismo ou mudança de tratamento.","Peça orientações antes de esporte novo, viagem/altitude ou procedimento. Se anatomia, saturação habitual ou plano de urgência estiverem indefinidos, solicite resumo da cardiologia, sem tentar deduzi-los do rótulo genérico."]},"ageMap":{"u3m":"Cianose nova ou pior que o padrão documentado, respiração difícil, mamada fraca com sonolência/má perfusão ou temperatura de 38°C ou mais exige avaliação imediata. Uma cardiopatia crítica pode piorar rapidamente; não trate em casa nem espere a próxima consulta.","3a5m":"Observe vigor das mamadas, pausas, suor, fraldas, peso e cor em relação ao habitual. Algumas cardiopatias podem ter crises de cianose nesta idade; use apenas o plano ensinado e chame ajuda se a crise não melhorar rapidamente ou houver moleza/falta de ar.","6a11m":"Compare alimentação, interação, movimento e urina com o padrão habitual. Não force alimentação se houver esforço respiratório ou sonolência; mudança súbita da cor com moleza, desmaio ou convulsão é emergência.","1a":"Queda de brincadeira, mais pausas, recusa alimentar ou menos fraldas justificam contato precoce. Cor pior, falta de ar ou deterioração rápida exige emergência; mantenha alimentação e líquidos conforme o plano da equipe.","2a5":"Observe se a criança deixa de acompanhar colegas, fica mais azul/cinza, se agacha repetidamente ou apresenta tontura/desmaio. Escola e cuidadores devem conhecer o plano individual; não confunda essas mudanças com cansaço normal.","6a11":"Acompanhe tolerância para caminhar, subir escadas e brincar, além de crescimento e aprendizagem. Síncope no esforço, dor torácica importante ou palpitação com mal-estar exige avaliação urgente; atividade permitida deve ser individualizada.","12a17":"Inclua o adolescente no plano e na transição para cardiologia de adultos. Revise adesão, escola, esporte e uso de energéticos/suplementos; não esconder desmaio, cianose pior, hemoptise ou palpitação para continuar a atividade.","unknown":"Confirme idade, anatomia, cirurgias e padrão habitual antes de aplicar recomendações específicas. Independentemente da idade, alteração súbita de cor, consciência, respiração ou perfusão exige atendimento imediato."},"refs":[{"id":"pais20261105_op3114_1","name":"About Congenital Heart Defects","url":"https://www.cdc.gov/heart-defects/about/index.html"},{"id":"pais20261105_op3114_2","name":"Symptoms and Diagnosis of Congenital Heart Disease","url":"https://www.heart.org/en/health-topics/congenital-heart-defects/symptoms--diagnosis-of-congenital-heart-defects"},{"id":"pais20261105_op3114_3","name":"Feeding Tips for Your Baby with CHD","url":"https://www.heart.org/en/health-topics/congenital-heart-defects/care-and-treatment-for-congenital-heart-defects/feeding-tips-for-your-baby-with-chd"},{"id":"pais20261105_op3114_4","name":"How Congenital Heart Disease Affects Children","url":"https://www.heart.org/en/health-topics/congenital-heart-defects/the-impact-of-congenital-heart-defects/chds-impact-on-children"},{"id":"pais20261105_op3114_5","name":"Cyanotic episodes in congenital heart disease","url":"https://www.rch.org.au/clinicalguide/guideline_index/Cyanotic_Episodes_in_Congenital_Heart_Disease/"},{"id":"pais20261105_op3114_6","name":"Tetralogy spells (tet spells)","url":"https://www.childrens.health.qld.gov.au/health-a-to-z/cardiac/tet-spells"},{"id":"pais20261105_op3114_7","name":"Interstage Home Monitoring for Infants With Single Ventricle Heart Disease — Top Things to Know","url":"https://professional.heart.org/en/science-news/interstage-home-monitoring-for-infants-with-single-ventricle-heart-disease/top-things-to-know"},{"id":"pais20261105_op3114_8","name":"Insuficiência Cardíaca na Criança — GPA nº 158","url":"https://www.sbp.com.br/fileadmin/user_upload/sbp/2024/agosto/14/24449f-GPA_-Insuficiencia_Cardiaca_na_Crc.pdf"},{"id":"pais20261105_op3114_9","name":"Recognition of the seriously unwell neonate and young infant","url":"https://www.rch.org.au/clinicalguide/guideline_index/Recognition_of_the_seriously_unwell_neonate_and_young_infant/"},{"id":"pais20261105_op3114_10","name":"Fever in children","url":"https://www.rch.org.au/kidsinfo/fact_sheets/Fever_in_children/"},{"id":"pais20261105_op3114_11","name":"Infective Endocarditis","url":"https://www.heart.org/en/health-topics/infective-endocarditis"}],"aliases":["Cardiopatia congênita cianótica","Cardiopatia congênita cianótica — apresentação pediátrica aguda","Cardiopatia congênita cianótica — evolução complicada/refratária","Cardiopatia congênita cianótica — forma grave/crítica"],"alwaysUrgent":false,"resultPath":"references/orientacoes-validadas/parallel-results/REVIEW-20261105-OP-3114.json","resultHash":"2e7d54c150a04eb6a73e8e672689b93e6910b372fbec794ada51b27a701aae7a"},{"jobId":"OP-3118","key":"pps_catalog_10c029f168bd5dcf","label":"Catarata congênita — registro no PPS","specific":true,"entity":"Opacidade do cristalino presente ao nascimento ou reconhecida muito cedo na infância, unilateral ou bilateral e de impacto visual variável; o rótulo não define densidade, posição, lateralidade, causa, comorbidade ocular ou sistêmica, nem autoriza tratar leucocoria como catarata confirmada","assessment":"{\"classification\":\"VALID_PEDIATRIC_SIGHT_THREATENING_CONGENITAL_LENS_OPACITY_REQUIRING_URGENT_DIAGNOSTIC_CONFIRMATION\",\"normalized_entity\":\"Catarata congênita ou infantil precoce\",\"assessment\":\"Catarata é opacidade do cristalino. O termo congênita indica presença ao nascimento, enquanto catarata infantil pode incluir opacidade reconhecida ou desenvolvida nos primeiros meses/anos; o cadastro é preservado sem presumir o momento exato de início. O impacto depende de lateralidade, localização, extensão, densidade e interferência no eixo visual: opacidades pequenas podem apenas exigir vigilância, enquanto opacidades visualmente significativas podem impedir o desenvolvimento visual e provocar ambliopia. Leucocoria é um sinal — pupila/reflexo branco — e não sinônimo de catarata: também pode ocorrer em retinoblastoma, doença retiniana, descolamento de retina, infecção e outras condições, algumas ameaçadoras à vida. Ambliopia é redução do desenvolvimento visual causada por imagem inadequada no cérebro e pode persistir mesmo depois de tratar a opacidade. A ficha orienta reconhecimento, proteção e encaminhamento; não escolhe colírio, exame, oclusão, lente, cirurgia, anestesia ou investigação etiológica.\",\"reconciliation\":{\"congenital_vs_infantile\":\"Congênita significa presente ao nascimento; infantil descreve catarata identificada ou desenvolvida na infância. O registro não permite datar o início nem dizer se houve progressão.\",\"lens_opacity_vs_leukocoria\":\"Catarata é opacidade do cristalino; leucocoria é aparência branca da pupila ou reflexo branco. Uma foto ou inspeção doméstica não localiza a causa dentro do olho.\",\"retinoblastoma\":\"Retinoblastoma é tumor intraocular e diagnóstico diferencial urgente de leucocoria. Não deve ser descartado porque a criança parece bem ou porque alguém sugeriu catarata.\",\"amblyopia\":\"Ambliopia é consequência funcional do desenvolvimento visual inadequado; não é a opacidade do cristalino. Pode exigir tratamento próprio e seguimento prolongado mesmo após restauração do eixo visual.\",\"laterality_and_severity\":\"Unilateral e bilateral não são equivalentes; o risco e o plano dependem de densidade, posição, visão, idade, olho contralateral e achados associados. Nem toda catarata exige cirurgia, mas toda suspeita em bebê requer avaliação rápida.\",\"etiology\":\"Podem existir formas isoladas, familiares, genéticas, metabólicas, associadas a infecções gestacionais, anomalias oculares ou trauma; muitas crianças não têm causa sistêmica identificada. Nenhuma etiologia deve ser presumida pelo nome isolado.\",\"counting_effect\":\"UMA_ENTIDADE_CLINICA_ESPECIFICA; conta-se catarata congênita/infantil precoce como uma entidade após integração e publicação. Leucocoria, retinoblastoma, ambliopia e causas etiológicas permanecem sinais, diferenciais, consequências ou condições associadas e não somam doenças cobertas.\"},\"not_automatically_equivalent_to\":[\"Leucocoria ou reflexo branco sem diagnóstico anatômico\",\"Retinoblastoma, descolamento de retina, retinopatia da prematuridade, doença de Coats ou infecção intraocular\",\"Ambliopia isolada\",\"Catarata traumática, medicamentosa, inflamatória ou metabólica confirmada\",\"Qualquer opacidade de córnea ou alteração do vítreo/retina\",\"Indicação automática de colírio, tampão, óculos, lente de contato, cirurgia, anestesia, exame laboratorial ou investigação genética\"],\"pediatric_scope\":\"Aplica-se do período neonatal à adolescência para catarata presente ao nascimento ou reconhecida precocemente. Recém-nascidos e lactentes podem não demonstrar perda visual claramente; reflexo vermelho alterado, leucocoria, pouca fixação, dificuldade para seguir faces/objetos, estrabismo ou nistagmo são pistas. Crianças maiores podem relatar visão turva, assimetria entre os olhos, halos, dificuldade em pouca luz, leitura ruim ou esbarrões. O risco de ambliopia é maior durante o desenvolvimento visual e exige seguimento mesmo quando a opacidade é pequena ou já foi tratada.\",\"counting_rule\":\"Contar este ID como um registro específico e uma entidade clínica somente depois de integração, testes e publicação. Não contar leucocoria, retinoblastoma, ambliopia, estrabismo, nistagmo, causa genética/metabólica/infecciosa ou estado pós-operatório como diagnósticos resolvidos por esta ficha.\",\"critical_context_to_confirm\":[\"Idade atual, idade na primeira suspeita e resultado documentado do teste do reflexo vermelho\",\"Um ou ambos os olhos, densidade, posição e interferência no eixo visual avaliadas por oftalmologia\",\"Fixação e seguimento de faces/objetos, alinhamento, nistagmo e visão funcional apropriada à idade\",\"Presença de leucocoria observada ao vivo ou repetida em fotografias e se ocorre em um ou ambos os olhos\",\"História familiar de catarata infantil, retinoblastoma ou outra doença ocular precoce\",\"Prematuridade, trauma ocular, infecção gestacional conhecida, síndrome, alteração metabólica ou outra condição sistêmica já documentada\",\"Tratamentos já prescritos, incluindo correção óptica, lente de contato, oclusão e cuidados pós-operatórios\",\"Plano do oftalmologista pediátrico, retornos, contatos de urgência e barreiras para comparecer\"],\"reason\":\"Entidade pediátrica válida e potencialmente ameaçadora à visão, sustentada por fontes governamentais, sociedades profissionais e coortes primárias. Há evidência suficiente para orientar famílias quanto a sinais, urgência, risco de ambliopia e adesão, sem inferir causa nem prescrever intervenção.\",\"next_action\":\"Integrar como ficha específica e testar a prioridade de leucocoria/reflexo vermelho anormal, a diferenciação de retinoblastoma e ambliopia, as oito faixas etárias e a ausência de tratamento automático antes de publicar.\"}","sections":{"CUIDADOS EM CASA":["Catarata congênita é uma opacidade do cristalino, a lente natural dentro do olho. Pode afetar um ou ambos os olhos e variar de um pequeno ponto sem repercussão até uma opacidade que bloqueia a formação da visão.","Pupila branca ou reflexo branco em foto chama-se leucocoria e não confirma catarata. Como também pode ser causado por retinoblastoma e outras doenças graves, procure avaliação oftalmológica imediatamente; não espere a próxima consulta de rotina.","Observe se o bebê fixa o rosto, acompanha luz suave ou objeto, usa os dois olhos de modo semelhante e se surgiu desvio ou tremor repetido dos olhos. Em crianças maiores, pergunte sobre visão turva, dificuldade para ler, enxergar à noite ou esbarrar.","Guarde fotos que mostrem reflexo branco repetido e informe quando e em qual olho ocorreu, mas não use flash, lanterna ou aplicativo repetidamente para tentar confirmar ou excluir doença em casa.","Proteja os olhos de trauma, mantenha iluminação confortável e organize a casa para reduzir quedas. Na escola, sente a criança onde enxergue melhor e forneça material ampliado apenas se isso já estiver no plano visual.","Catarata não é contagiosa. A causa pode ser isolada, familiar ou associada a outras condições, mas o nome sozinho não permite concluir infecção, síndrome, herança ou problema metabólico."],"MEDIDAS SEM REMÉDIOS":["Compare o comportamento visual de cada olho sem pressionar ou esfregar: mudança de fixação, seguimento, alinhamento ou preferência marcante por um olho deve ser comunicada rapidamente.","Use óculos, lente de contato ou tampão somente como prescrito. Não improvise oclusão, não aumente horas por conta própria e não cubra o olho com melhor visão sem plano, pois a dose de oclusão precisa ser individual.","Se houver lente de contato ou correção óptica prescrita após tratamento, siga a técnica de limpeza, colocação, retirada e substituição ensinada pela equipe. Procure ajuda se não conseguir usar com segurança.","Não pressione, massageie nem tente limpar uma mancha que parece estar dentro da pupila. Não pingue leite materno, chá, soro caseiro ou qualquer produto no olho.","Mantenha estímulos visuais apropriados à idade em ambiente seguro — rosto, brinquedo contrastante, leitura e brincadeiras — sem luz intensa dirigida ao olho e sem substituir o tratamento da ambliopia indicado pela equipe.","Informe à creche ou escola sobre a limitação visual, correção óptica e sinais de urgência. Atividade escolar e convívio podem continuar conforme a visão e o plano individual; não há isolamento por catarata."],"MEDICAMENTOS":["Nenhum colírio, pomada, vitamina, suplemento ou remédio caseiro dissolve catarata congênita. Esta orientação não indica medicamento, dose, exame, tampão, óculos, lente ou cirurgia.","Não use colírio com corticoide, antibiótico, vasoconstritor, anestésico ou produto de outra pessoa. Colírios podem causar dano e alguns favorecem catarata ou mascaram complicações.","Se o oftalmologista prescreveu colírios antes ou depois de procedimento, use apenas o nome, o olho, o número de gotas, o horário e o período escritos para esta criança. Não prolongue nem interrompa por conta própria.","Se uma aplicação foi esquecida, repetida ou administrada no olho errado, ou se a ponta do frasco encostou no olho, procure orientação do serviço/farmacêutico em vez de compensar sozinho.","Leve ao retorno frascos, fotos dos rótulos e a lista de horários. Informe alergia, ardor intenso, inchaço, secreção, piora da vermelhidão ou dificuldade para administrar.","Não dê medicamento sistêmico nem faça investigação por conta própria para uma suposta causa genética, metabólica ou infecciosa; a avaliação depende de lateralidade, exame ocular, história e achados sistêmicos."],"ALIMENTAÇÃO E LÍQUIDOS":["Não existe alimento, dieta, suco, vitamina ou suplemento que clareie o cristalino ou trate a ambliopia. Mantenha alimentação e hidratação adequadas à idade, salvo plano médico diferente.","A catarata isolada não exige troca de fórmula nem retirada de leite ou açúcar. Continue a alimentação habitual, salvo orientação da equipe. Se houver suspeita de doença metabólica, procure avaliação urgente e siga o plano específico; não espere diagnóstico definitivo para buscar ajuda nem faça dieta de exclusão por conta própria.","Não ofereça megadoses de vitamina A, antioxidantes ou produtos anunciados para a visão. Eles não substituem avaliação e podem causar toxicidade.","Em recém-nascido ou bebê pequeno, recusa alimentar importante, vômitos repetidos, muita sonolência, icterícia com piora ou dificuldade para despertar exigem avaliação imediata. Baixo ganho de peso e atraso do desenvolvimento também precisam ser investigados, não atribuídos à catarata.","Se houver procedimento com anestesia programado, siga somente o jejum fornecido pelo serviço; esta ficha não define tempo de jejum para bebês, crianças ou adolescentes.","Após procedimento, siga as orientações do hospital sobre líquidos e alimentação e procure ajuda se a criança não consegue beber, vomita repetidamente ou fica muito sonolenta."],"VOLTE IMEDIATAMENTE AO PRONTO ATENDIMENTO":["Pupila ou reflexo branco novo ou ainda sem avaliação exige atendimento oftalmológico imediato, para excluir retinoblastoma e outras doenças graves; se não houver acesso rápido, procure pronto atendimento. Teste do olhinho alterado exige encaminhamento urgente, sem aguardar consulta de rotina. Catarata já confirmada e estável segue o plano da equipe.","Procure emergência após perfuração, contato químico ou objeto preso no olho; após pancada, procure imediatamente se houver dor, sangramento, pupila deformada ou visão pior. Não pressione nem tente retirar objeto preso. Em respingo químico, comece a lavar com bastante água limpa enquanto busca ajuda, sem esperar consulta.","Dor ocular forte, olho muito vermelho, sensibilidade intensa à luz, dor de cabeça com vômitos, inchaço rápido ou perda súbita da visão exige emergência; esses sinais não são explicados por uma catarata congênita estável.","Após cirurgia ou outro procedimento ocular, procure o serviço imediatamente se houver dor crescente, vermelhidão/inchaço que piora, secreção, sangramento, trauma, vômitos repetidos, febre com prostração ou aparente queda da visão.","Bebê que deixa de fixar rostos, perde uma habilidade visual já adquirida, passa a desviar um olho de forma constante ou desenvolve movimentos repetidos dos olhos precisa de avaliação urgente; se houver leucocoria, vá imediatamente.","Se a criança fica inconsciente, tem convulsão, trauma grave ou alteração neurológica súbita, acione o SAMU 192. Não ofereça alimento, líquido ou medicamento pela boca enquanto não estiver plenamente desperta."],"QUANDO REAVALIAR":["Suspeita de catarata em recém-nascido ou lactente, teste do olhinho alterado, leucocoria ou reflexo vermelho assimétrico exige avaliação rápida por oftalmologista com experiência em crianças; não espere a visão parecer pior.","Se a catarata foi confirmada, cumpra o prazo definido pela oftalmologia. O momento de observar ou intervir depende de idade, um ou dois olhos, densidade, posição e efeito visual; esta ficha não fornece uma idade cirúrgica única.","Opacidades pequenas que não exigem intervenção imediata ainda precisam de retornos regulares, pois podem progredir ou causar erro de grau e ambliopia sem que a criança reclame.","Depois de qualquer tratamento, mantenha correção óptica, oclusão e retornos exatamente como prescritos. Remover a opacidade não encerra o cuidado: o cérebro ainda precisa desenvolver visão e complicações podem surgir ao longo dos anos.","Antecipe o retorno se a criança passa a usar menos um olho, aproxima muito objetos, inclina a cabeça, desvia ou treme os olhos, perde rendimento, esbarra mais, relata visão turva/halos ou se a família não consegue cumprir lentes, tampão ou colírios.","Leve caderneta, resultado do teste do olhinho, fotos do reflexo, história familiar, lista de tratamentos e dúvidas. Peça um plano escrito com diagnóstico, lateralidade, objetivo de cada medida, sinais de alarme e próximo prazo."]},"ageMap":{"u3m":"Confirmar teste do olhinho/reflexo vermelho, fixação e seguimento. Reflexo ausente, assimétrico ou branco, pupila branca, pouca fixação ou anormalidade ocular requer encaminhamento urgente; não esperar o próximo retorno nem presumir catarata em vez de retinoblastoma.","3a5m":"Observar se acompanha rostos e objetos com os dois olhos, se surgiu estrabismo ou nistagmo e se prefere um lado. Qualquer leucocoria é imediata; atraso visual ou desvio persistente precisa de avaliação rápida.","6a11m":"Comparar alcance de brinquedos, exploração e seguimento visual sem testes caseiros agressivos. Reflexo branco novo ou ainda não investigado exige avaliação oftalmológica imediatamente; se não houver acesso rápido, procure pronto atendimento. Esbarrões, assimetria entre os olhos, desvio ou tremor ocular novo devem antecipar a avaliação; mantenha correção e oclusão somente como prescritas.","1a":"Avaliar reconhecimento de pessoas/objetos, deslocamento seguro e alinhamento. Criança pequena pode não reclamar de um olho ruim; inclinação da cabeça, preferência ocular, desvio ou regressão visual devem antecipar o retorno.","2a5":"Monitorar desenho, brincadeiras, escadas, distância para ver e tolerância a óculos/tampão. Informar creche; dificuldade funcional, novo estrabismo ou leucocoria não deve ser atribuída a comportamento.","6a11":"Perguntar separadamente sobre cada olho, leitura, quadro, esporte, visão noturna e esbarrões. Ajustes escolares podem ser necessários; não abandonar seguimento após cirurgia ou por bom desempenho com o outro olho.","12a17":"O adolescente deve conhecer lateralidade, correção óptica, oclusão/colírios se prescritos, alarmes e consultas. Queda visual, dor, trauma ou uso inseguro de lente/colírio exige contato rápido; garantir transição sem interrupção do seguimento.","unknown":"Confirmar idade, início, um ou dois olhos, reflexo vermelho, leucocoria, fixação/visão, estrabismo/nistagmo, trauma, cirurgia e plano atual. Sem esses dados, aplicar apenas proteção, proibição de tratamento caseiro e encaminhamento urgente diante de reflexo branco ou perda visual."},"refs":[{"id":"pais20261105_op3118_1","name":"Cuidado Neonatal — Teste do Olhinho","url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/s/saude-da-crianca/cuidado-neonatal"},{"id":"pais20261105_op3118_2","name":"Cataract","url":"https://www.aapos.org/glossary/cataract"},{"id":"pais20261105_op3118_3","name":"Leukocoria","url":"https://www.aapos.org/glossary/leukocoria"},{"id":"pais20261105_op3118_4","name":"Newborn and infant physical examination screening programme handbook — eye screening","url":"https://www.gov.uk/government/publications/newborn-and-infant-physical-examination-programme-handbook/newborn-and-infant-physical-examination-screening-programme-handbook"},{"id":"pais20261105_op3118_5","name":"Childhood cataracts","url":"https://www.nhs.uk/conditions/childhood-cataracts/"},{"id":"pais20261105_op3118_6","name":"Ten-year outcomes of congenital cataract surgery performed within the first six months of life","url":"https://pubmed.ncbi.nlm.nih.gov/38517986/"},{"id":"pais20261105_op3118_7","name":"Clinical Practice Guidelines: Acute eye injury","url":"https://www.rch.org.au/clinicalguide/guideline_index/Acute_eye_injury/"}],"aliases":["Catarata congênita"],"alwaysUrgent":false,"resultPath":"references/orientacoes-validadas/parallel-results/REVIEW-20261105-OP-3118.json","resultHash":"ee4fc24504583285fcd0de005b0a21b6983dff002ade9094255d76e3ee0a4f35"}],sources={...base.sources};for(const r of records)for(const s of r.refs)sources[s.id]={name:s.name,url:s.url};const byKey=new Map(records.map(r=>[r.key,r])),norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim(),byName=new Map(records.map(r=>[norm(r.label),r]));function inherited(fn){const current=root.PaisGuide;root.PaisGuide=base;try{return fn();}finally{root.PaisGuide=current;}}function rowFor(v){return byKey.get(String(v||''))||byName.get(norm(v))||null;}function sectionsFor(row,age){const sections=Object.entries(row.sections).map(([title,items])=>({title,items:[...items]})),care=sections.find(s=>s.title==='CUIDADOS EM CASA'),note=row.ageMap[age]||row.ageMap.unknown;if(care&&note)care.items.push('Para esta faixa etária: '+note);return sections;}const topics=base.topics.map(t=>{const r=byKey.get(t.key);return r?{...t,generalGuidanceMode:false,catalogOnly:false,specificGuidance:r.specific,termResolution:!r.specific,sections:sectionsFor(r,'unknown'),refs:r.refs.map(s=>s.id),clinicalEntity:r.entity,termAssessment:r.assessment,directedReview:'2026-11-05',urgency:r.alwaysUrgent||t.urgency}:t;});function resolve(v){const r=rowFor(v);return r?topics.find(t=>t.key===r.key):inherited(()=>base.resolve(v));}function build(input={}){const p=input&&typeof input==='object'?input:{},row=rowFor(p.diagnosis)||(()=>{const t=inherited(()=>base.resolve(p.diagnosis));return t&&byKey.get(t.key);})();if(!row)return inherited(()=>base.build(input));const age=p.age===undefined||p.age===null||p.age===''?'unknown':p.age;if(!Object.hasOwn(base.ages,age))return{ok:false,code:'AGE_INVALID',message:'Selecione uma faixa etária válida.'};const previous=inherited(()=>base.build({...p,age}));if(!previous?.ok||previous.specificBodyAllowed===false)return previous;if(p.reviewed!==true&&p.danger!=='yes')return{ok:false,code:'REVIEW_REQUIRED',message:'Confirme a avaliação do diagnóstico pela equipe. O site não decide alta.'};const qualifiedAlias=(row.aliases||[]).some(a=>norm(a)===norm(p.diagnosis))&&/grave|critic|complicad|refratari/.test(norm(p.diagnosis));const urgent=row.alwaysUrgent||qualifiedAlias||p.danger==='yes'||previous.mode==='urgent';let sections=sectionsFor(row,age);if(urgent)sections=[{title:'ATENDIMENTO URGENTE',items:['Esta condição exige avaliação presencial urgente. Procure atendimento imediato e não use esta ficha para adiar avaliação.']},...sections];const clean=(v,n)=>typeof v==='string'?v.replace(/[\u0000-\u001f\u007f]/g,' ').trim().slice(0,n):'',notes=clean(p.notes,1400),plan=clean(p.returnPlan,200);if(notes)sections.push({title:'COMPLEMENTO DA CONSULTA',items:[notes]});if(plan){const f=sections.find(s=>s.title==='QUANDO REAVALIAR');if(f)f.items.push('Retorno combinado: '+plan);}const text='ORIENTAÇÕES AOS PAIS — '+row.label+'\nFaixa etária: '+base.ages[age]+'\n\n'+sections.map((s,i)=>(i+1)+'. '+s.title+'\n'+s.items.map(x=>'• '+x).join('\n')).join('\n\n');return{...previous,ok:true,mode:urgent?'urgent':'guidance',topic:row.key,label:row.label,sections,refs:row.refs.map(s=>s.id),text,warnings:urgent?['Avaliação prioritária necessária; esta ficha não autoriza alta.']:[],effectiveAgeBand:age,directedGuidance:true,termResolution:!row.specific,termAssessment:row.assessment};}function audit(){const old=inherited(()=>base.audit()),issues=[...(old.issues||[])];for(const r of records){const t=topics.find(x=>x.key===r.key);if(!t||t.label!==r.label||t.specificGuidance!==r.specific||t.termResolution!==!r.specific||!r.refs.every(s=>sources[s.id]))issues.push('multisystem-six-20261105:'+r.key);}return{...old,ok:!issues.length,issues,topics:topics.length};}root.PaisGuide={...base,sources,topics,resolve,build,audit,multisystemSix20261105:{keys:records.map(r=>r.key),checked_at:"2026-11-05"}};})(typeof window!=='undefined'?window:globalThis);
